package com.brizking.constructionrecords;
import android.app.Activity;import android.content.Context;import android.os.Bundle;import android.webkit.*;import android.view.ViewGroup;import android.print.*;
public class MainActivity extends Activity {private WebView webView,printWebView;
@Override protected void onCreate(Bundle b){super.onCreate(b);webView=new WebView(this);webView.setLayoutParams(new ViewGroup.LayoutParams(-1,-1));WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);webView.addJavascriptInterface(new Bridge(),"BrizKingNative");webView.setWebViewClient(new WebViewClient());webView.setWebChromeClient(new WebChromeClient());setContentView(webView);if(b==null)webView.loadUrl("file:///android_asset/index.html");else webView.restoreState(b);}
public class Bridge{@JavascriptInterface public void printHtml(final String html,final String title){runOnUiThread(()->{printWebView=new WebView(MainActivity.this);printWebView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){PrintManager pm=(PrintManager)getSystemService(Context.PRINT_SERVICE);String n=(title==null?"BrizKing-Document":title).replaceAll("[^A-Za-z0-9._-]","_");pm.print(n,v.createPrintDocumentAdapter(n),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setColorMode(PrintAttributes.COLOR_MODE_COLOR).build());}});printWebView.loadDataWithBaseURL(null,html,"text/HTML","UTF-8",null);});}}
@Override protected void onSaveInstanceState(Bundle b){webView.saveState(b);super.onSaveInstanceState(b);}@Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}}